from collections import deque
def f(g):
    n,m=len(g),len(g[0]); seen=[[False]*m for _ in range(n)]
    q=deque()
    for r in range(n):
        for c in range(m):
            if g[r][c]==0 and (r==0 or r==n-1 or c==0 or c==m-1):
                seen[r][c]=True; q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<n and 0<=nc<m and g[nr][nc]==0 and not seen[nr][nc]:
                seen[nr][nc]=True; q.append((nr,nc))
    # determine color of enclosed region: collect neighboring non-zero colors of unreachable 0s
    fill={}
    for r in range(n):
        for c in range(m):
            if not seen[r][c] and g[r][c]==0:
                nb=set()
                for dr in(-1,0,1):
                    for dc in(-1,0,1):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<n and 0<=nc<m and g[nr][nc]!=0:
                            nb.add(g[nr][nc])
                if len(nb)==1: fill[(r,c)]=nb.pop()
    return [[fill.get((r,c),g[r][c]) for c in range(m)] for r in range(n)]
